// Node reference port of tests/integration/ExampleFiles.cs::SensorMap (the public-safe synthetic
// sensor-map example served read-only by the Preview host at /api/sensor-map).
//
// Why this exists: the .NET SDK is not available in the Arena sandbox, so the Owner critical
// topology correction (108 Product Sensors; I7 and I16 are normal Sensors; 216 assigned Product TC
// measurements) could not be regenerated by the authoritative .NET generator here. This port
// reproduces the generator's fixed formulas (the C# header states the formulas are byte-stable and
// reproducible by a Node reference generator) so the committed example stays consistent with the
// corrected topology until the Owner regenerates it locally with .NET.
//
// The port was proven against the committed 106-Sensor example before the correction: with
// SENSOR_LOCATIONS=106 and the legacy device distribution [14,14,13,13,13,13,13,13] it reproduces
// config/examples/sensor-map.example.json byte for byte (see --legacy-proof below).
//
// Synthetic values only. No Production value, address, register, coordinate or timing constant.
// No network, no device, no clock.
//
// Usage:
//   node tools/sensor-map-example/generate.mjs            -> prints the corrected (108) example
//   node tools/sensor-map-example/generate.mjs --write    -> rewrites config/examples/sensor-map.example.json
//   node tools/sensor-map-example/generate.mjs --legacy-proof
//                                                         -> prints the superseded 106 form (port proof only)

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const TARGET = join(HERE, '..', '..', 'config', 'examples', 'sensor-map.example.json');

export const LOGICAL_COLUMNS = 18;
export const LOGICAL_ROWS = 6;

/** Owner critical topology correction: every one of the 108 logical positions is a Product Sensor. */
export const CORRECTED = Object.freeze({
  sensorLocations: 108,
  thermocoupleChannels: 216,
  nonSensorGapSlots: Object.freeze([]),
  // Synthetic device distribution over the 108 scan positions (14 x 4 + 13 x 4 = 108).
  deviceCounts: Object.freeze([14, 14, 14, 14, 13, 13, 13, 13]),
  sensorsPerWall: Object.freeze({ LEFT: 24, REAR: 30, RIGHT: 24, FRONT: 30 }),
  notes: Object.freeze([
    'scanOrderSynthetic and tcChannels are SYNTHETIC example assignments (device distribution); tcChannels is an exact two-entry array (front = lower channel index, rear = higher), not Production data.',
    'Owner critical topology correction: I7 and I16 are normal Product Sensors. Every one of the 108 logical positions is a Sensor with exactly two thermocouple channels; no position is a gap or a placement anchor.',
    'The logical matrix and wall distribution are the Owner-confirmed structure (108 locations, 216 channels).',
  ]),
});

/** Superseded 106-Sensor form, kept ONLY to prove the port against the previously committed file. */
export const LEGACY_SUPERSEDED = Object.freeze({
  sensorLocations: 106,
  thermocoupleChannels: 212,
  nonSensorGapSlots: Object.freeze([
    Object.freeze({ logicalId: 'I7', anchorWaterJetId: 'WJ3', row: 5, column: 7 }),
    Object.freeze({ logicalId: 'I16', anchorWaterJetId: 'WJ1', row: 5, column: 16 }),
  ]),
  deviceCounts: Object.freeze([14, 14, 13, 13, 13, 13, 13, 13]),
  sensorsPerWall: Object.freeze({ LEFT: 24, REAR: 29, RIGHT: 24, FRONT: 29 }),
  notes: Object.freeze([
    'scanOrderSynthetic and tcChannels are SYNTHETIC example assignments (device distribution); tcChannels is an exact two-entry array (front = lower channel index, rear = higher), not Production data.',
    'NON_SENSOR_GAP slots (I7, I16) are placement anchors, not Sensors; they carry no sensorId, no thermocouple channels, and only the Water Jet each physically anchors.',
    'The logical matrix and wall distribution are the Owner-confirmed structure (106 locations, 212 channels).',
  ]),
});

const LABEL = 'PUBLIC-SAFE EXAMPLE - SYNTHETIC - INCOMPLETE BY DESIGN - NOT FOR DEPLOYMENT';
const FIXTURE_STATUS = 'PROVISIONAL STRUCTURAL FIXTURE - OWNER-LOCAL .NET GENERATION REQUIRED';

const WALL_COLUMNS = Object.freeze({ LEFT: [1, 4], REAR: [5, 9], RIGHT: [10, 13], FRONT: [14, 18] });

export function wallForColumn(column) {
  for (const [wall, [first, last]] of Object.entries(WALL_COLUMNS)) {
    if (column >= first && column <= last) return wall;
  }
  throw new RangeError(`logical column ${column} is outside the 18-column matrix`);
}

export function sensorIdFor(row, column) {
  switch (row) {
    case 1: return `G+${200 + column}`;
    case 2: return `G+${100 + column}`;
    case 3: return `G${column}`;
    case 4: return `H${column}`;
    case 5: return `I${column}`;
    case 6: return `J${column}`;
    default: throw new RangeError('logical row must be 1-6');
  }
}

function deviceFor(counts, scanOrder) {
  let remaining = scanOrder;
  for (let d = 0; d < counts.length; d += 1) {
    if (remaining <= counts[d]) return { deviceId: `SYN-TC-${String(d + 1).padStart(2, '0')}`, index: remaining - 1 };
    remaining -= counts[d];
  }
  throw new Error('scan order outside device distribution');
}

export function buildSensorMapExample(profile = CORRECTED) {
  const slots = [];
  let scan = 0;
  for (let row = 1; row <= LOGICAL_ROWS; row += 1) {
    for (let col = 1; col <= LOGICAL_COLUMNS; col += 1) {
      const gap = profile.nonSensorGapSlots.find((g) => g.row === row && g.column === col) ?? null;
      const wall = wallForColumn(col);
      const [first] = WALL_COLUMNS[wall];
      const slot = {
        slotId: `SLOT-R${row}-C${String(col).padStart(2, '0')}`,
        positionKind: gap ? 'NON_SENSOR_GAP' : 'SENSOR',
        wall,
        logicalColumn: col,
        logicalRow: row,
        wallColumn: col - first + 1,
        wallRow: row,
        sensorId: gap ? null : sensorIdFor(row, col),
        gapAnchorForWaterJetId: gap ? gap.anchorWaterJetId : null,
      };
      if (gap) {
        slot.logicalLabel = `I${col}`;
      } else {
        scan += 1;
        slot.scanOrderSynthetic = scan;
        const { deviceId, index } = deviceFor(profile.deviceCounts, scan);
        slot.tcChannels = [
          `${deviceId}:CH${String(2 * index).padStart(2, '0')}`,
          `${deviceId}:CH${String(2 * index + 1).padStart(2, '0')}`,
        ];
      }
      slots.push(slot);
    }
  }
  if (scan !== profile.sensorLocations) {
    throw new Error(`generated ${scan} Sensor positions, profile expects ${profile.sensorLocations}`);
  }
  return {
    _label: LABEL,
    logicalMatrix: {
      columns: LOGICAL_COLUMNS,
      rows: LOGICAL_ROWS,
      sensorLocations: profile.sensorLocations,
      thermocoupleChannels: profile.thermocoupleChannels,
      sensorsPerWall: { ...profile.sensorsPerWall },
      slots,
    },
    notes: [...profile.notes],
    fixtureStatus: FIXTURE_STATUS,
  };
}

/** System.Text.Json indented output with the default (strict) encoder: '+' is emitted as \u002B. */
export function serializeLikeContractJson(value) {
  return JSON.stringify(value, null, 2).replace(/\+/g, '\\u002B');
}

const invokedDirectly = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (invokedDirectly) {
  const legacy = process.argv.includes('--legacy-proof');
  const text = serializeLikeContractJson(buildSensorMapExample(legacy ? LEGACY_SUPERSEDED : CORRECTED));
  if (process.argv.includes('--write')) {
    if (legacy) throw new Error('--legacy-proof is read-only; the superseded form is never written');
    writeFileSync(TARGET, text);
    process.stdout.write(`wrote ${TARGET}\n`);
  } else {
    process.stdout.write(text);
  }
}
